SELECT 'all 9 Coalition War Campaign creatures are in' AS assertion, count(*) AS got, 9 AS want
  FROM creatures WHERE slug IN ('devil-sloth', 'vampire-flat-worm', 'spiny-ravager', 'nmbyr-gorilla-man', 'tirrvol-sword-fist', 'quick-flex-alien', 'vanguard-brawler', 'trimadore', 'kremin-cyborg');
SELECT 'and 6 of them are the playable Burbs D-bees' AS assertion, count(*) AS got, 6 AS want
  FROM creatures WHERE slug IN ('devil-sloth', 'vampire-flat-worm', 'spiny-ravager', 'nmbyr-gorilla-man', 'tirrvol-sword-fist', 'quick-flex-alien', 'vanguard-brawler', 'trimadore', 'kremin-cyborg') AND playable = 1;
SELECT 'all 7 notable NPCs are in' AS assertion, count(*) AS got, 7 AS want
  FROM notable_npcs WHERE slug IN ('erin-tarn', 'sir-winslow-thorpe', 'jack-cavanaugh', 'emperor-karl-prosek', 'joseph-prosek-ii', 'general-cabot', 'general-ross-underhill');
SELECT 'the creatures carry 21 attacks' AS assertion, count(*) AS got, 21 AS want
  FROM stat_attacks WHERE owner_kind = 'creature' AND owner_slug IN ('devil-sloth', 'vampire-flat-worm', 'spiny-ravager', 'nmbyr-gorilla-man', 'tirrvol-sword-fist', 'quick-flex-alien', 'vanguard-brawler', 'trimadore', 'kremin-cyborg');
SELECT 'and the notables 18' AS assertion, count(*) AS got, 18 AS want
  FROM stat_attacks WHERE owner_kind = 'notable_npc' AND owner_slug IN ('erin-tarn', 'sir-winslow-thorpe', 'jack-cavanaugh', 'emperor-karl-prosek', 'joseph-prosek-ii', 'general-cabot', 'general-ross-underhill');

